package dev.s7a.strata.runtime

import dev.s7a.strata.node.DirtyMask
import dev.s7a.strata.node.DirtyPhase
import dev.s7a.strata.runtime.diagnostics.UiRenderMetric
import dev.s7a.strata.spi.InternalStrataRuntimeApi

/**
 * Expands downstream local phases and propagates measurement work to ancestors.
 */
@OptIn(InternalStrataRuntimeApi::class)
internal class DirtyTracker(
    private val monitoring: RenderMonitoring = RenderMonitoring(),
) {
    private var currentRevision: Long = 0L

    /**
     * Effective ancestry change token; ordinary phase invalidation preserves callback membership.
     */
    var structureRevision: Long = 0L
        private set

    /**
     * Whole-tree change token used to reject stale frame snapshots.
     *
     * The token changes whenever nonempty phase work or structural work is recorded.
     * Reads and writes are confined to the owning tree thread by the enclosing [UiTree].
     *
     * @return the current whole-tree change token.
     */
    val revision: Long
        get() = currentRevision

    /**
     * Records [mask] on [retained] and conservatively expands downstream work.
     *
     * @param retained the retained node whose phases changed.
     * @param mask the phases reported by an element or node-local change.
     */
    fun record(
        retained: RetainedEntry,
        mask: DirtyMask,
    ) {
        if (mask != DirtyMask.None) {
            monitoring.record(UiRenderMetric.LocalInvalidation, retained)
            advanceRevision()
        }
        val expanded = expand(mask)
        retained.dirty += expanded
        if (DirtyPhase.Measure in mask) {
            val ancestorMask = DirtyMask.of(DirtyPhase.Measure, DirtyPhase.Layout, DirtyPhase.Paint, DirtyPhase.Semantics)
            var ancestor = retained.parent
            while (ancestor != null) {
                monitoring.record(UiRenderMetric.AncestorInvalidation, ancestor)
                ancestor.dirty += ancestorMask
                ancestor = ancestor.parent
            }
        }
    }

    /**
     * Marks structural work on [retained] and all ancestors.
     *
     * @param retained the parent whose direct-child structure changed.
     */
    fun structural(retained: RetainedEntry) {
        structureRevision += 1L
        monitoring.record(UiRenderMetric.StructureInvalidation, retained)
        advanceRevision()
        var current: RetainedEntry? = retained
        while (current != null) {
            current.dirty += DirtyMask.All
            current = current.parent
        }
    }

    private fun expand(mask: DirtyMask): DirtyMask {
        var expanded = mask
        if (DirtyPhase.Measure in mask) {
            expanded += DirtyMask.of(DirtyPhase.Layout, DirtyPhase.Paint, DirtyPhase.Semantics)
        } else if (DirtyPhase.Layout in mask) {
            expanded += DirtyMask.of(DirtyPhase.Paint, DirtyPhase.Semantics)
        }
        return expanded
    }

    private fun advanceRevision() {
        currentRevision += 1L
    }
}
